def minimumTime(n: int, relations: list[list[int]], time: list[int]) -> int:
    from collections import defaultdict, deque
    adj = defaultdict(list)
    in_deg = [0] * (n + 1)
    for u, v in relations:
        adj[u].append(v)
        in_deg[v] += 1
    dp = [0] * (n + 1)
    q = deque([i for i in range(1, n + 1) if in_deg[i] == 0])
    for i in q:
        dp[i] = time[i - 1]
    while q:
        u = q.popleft()
        for v in adj[u]:
            dp[v] = max(dp[v], dp[u] + time[v - 1])
            in_deg[v] -= 1
            if in_deg[v] == 0:
                q.append(v)
    return max(dp)

